type Repo = { id: number; name: string; full_name: string; private: boolean; default_branch: string; description?: string };
type TreeItem = { path: string; type: 'blob' | 'tree'; sha: string; size?: number };
type StageEntry = { path: string; content: string | null; binary?: boolean };
type Commit = { sha: string; commit: { message: string; author?: { name?: string; date?: string } }; html_url: string };
const API = 'https://api.github.com';
const GH_SESSION = 'pothub.github.session';
const GH_STATE = 'pothub.github.state';
const GH_OAUTH = 'pothub.github.oauth';
const GH_WORKSPACE = 'pothub.github.workspace.v1';
function workspaceKey(user:string,repo?:string,branch?:string){return `${GH_WORKSPACE}:${user}${repo?':'+repo:''}${branch?':branch:'+encodeURIComponent(branch):''}`;}
function readWorkspace(user?:string,repo?:string,branch?:string){try{if(user){if(repo){if(branch)return JSON.parse(localStorage.getItem(workspaceKey(user,repo,branch))||'null');const active=localStorage.getItem(workspaceKey(user,repo));return active?JSON.parse(localStorage.getItem(workspaceKey(user,repo,active))||'null'):null;}const activeRepo=localStorage.getItem(workspaceKey(user));if(activeRepo)return readWorkspace(user,activeRepo);}return JSON.parse(localStorage.getItem(GH_WORKSPACE)||'null');}catch{return null;}}
function saveWorkspace(snapshot:any){try{if(snapshot?.user&&snapshot?.repo?.full_name&&snapshot?.branch){localStorage.setItem(workspaceKey(snapshot.user,snapshot.repo.full_name,snapshot.branch),JSON.stringify(snapshot));localStorage.setItem(workspaceKey(snapshot.user,snapshot.repo.full_name),snapshot.branch);localStorage.setItem(workspaceKey(snapshot.user),snapshot.repo.full_name);}else localStorage.setItem(GH_WORKSPACE,JSON.stringify(snapshot));}catch{}}
async function loadGithubToken(){try{if(Capacitor.isNativePlatform()){const {SecureStorage}=await import('@aparajita/capacitor-secure-storage');const v=await SecureStorage.get('pothub.github.token');return typeof v==='string'?v:'';}return localStorage.getItem(GH_SESSION)||'';}catch{return '';}}
async function saveGithubToken(token:string){try{if(Capacitor.isNativePlatform()){const {SecureStorage}=await import('@aparajita/capacitor-secure-storage');await SecureStorage.set('pothub.github.token',token);}else localStorage.setItem(GH_SESSION,token);}catch{throw new Error('Could not save GitHub session on this device.');}}
