const headers = (token: string) => ({ Authorization: `Bearer ${token}`, Accept: 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28' });
async function github<T>(token: string, path: string, init?: RequestInit): Promise<T> {
  const r = await fetch(`${API}${path}`, { ...init, headers: { ...headers(token), ...(init?.headers || {}) } });
  if (!r.ok) { const j = await r.json().catch(() => ({})); const detail=(j as {message?:string}).message; let hint=''; if(r.status===401)hint=' Token may be expired or invalid; reconnect with a new token.'; else if(r.status===403&&r.headers.get('x-ratelimit-remaining')==='0'){const reset=Number(r.headers.get('x-ratelimit-reset'));hint=reset?` Rate limit resets at ${new Date(reset*1000).toLocaleString()}.`:' GitHub rate limit reached.';}else if(r.status===403)hint=' Check token scopes and repository access permissions.';else if(r.status===404)hint=' Check the repository, branch, file path, or token repository access.';else if(r.status===409)hint=' The repository changed; refresh and retry.';else if(r.status===422)hint=' GitHub rejected this change; check branch rules, names, and validation.';throw new Error(`${detail||`GitHub request failed (${r.status})`}${hint}`); }
  return r.status === 204 ? undefined as T : r.json();
}
function from64(text: string) { const bin = atob(text.replace(/\n/g, '')); return new TextDecoder().decode(Uint8Array.from(bin, c => c.charCodeAt(0))); }
function lang(path: string) { const ext = path.split('.').pop()?.toLowerCase() || ''; const map: Record<string,string> = { ts:'TypeScript',tsx:'TSX',js:'JavaScript',jsx:'JSX',py:'Python',json:'JSON',md:'Markdown',css:'CSS',html:'HTML',yml:'YAML',yaml:'YAML',sh:'Shell',sql:'SQL',java:'Java',kt:'Kotlin',go:'Go',rs:'Rust',c:'C',cpp:'C++',xml:'XML',txt:'Text' }; return map[ext] || 'Plain text'; }
function fileIcon(path: string): IconName { const ext=path.split('.').pop()?.toLowerCase(); return ext==='ts'||ext==='tsx'||ext==='js'||ext==='jsx'||ext==='py'||ext==='go'||ext==='rs'?'code':'file'; }
function safePath(path: string) { const p=path.trim().replace(/^\/+/, ''); if(!p || p.split('/').some(x=>!x||x==='.'||x==='..')) throw new Error('Use a valid relative path without empty, . or .. segments.'); return p; }
function lineDiff(before:string,after:string){const a=before.split('\n'),b=after.split('\n');if(a.length*b.length>160000)return [{kind:'del' as const,text:'Diff omitted: file is too large for an in-browser line comparison.'},{kind:'add' as const,text:`Updated file (${b.length} lines).`}];const dp=Array.from({length:a.length+1},()=>new Uint16Array(b.length+1));for(let i=a.length-1;i>=0;i--)for(let j=b.length-1;j>=0;j--)dp[i][j]=a[i]===b[j]?dp[i+1][j+1]+1:Math.max(dp[i+1][j],dp[i][j+1]);const rows:{kind:'same'|'add'|'del';text:string}[]=[];let i=0,j=0;while(i<a.length||j<b.length){if(i<a.length&&j<b.length&&a[i]===b[j]){rows.push({kind:'same',text:a[i]});i++;j++;}else if(j<b.length&&(i===a.length||dp[i][j+1]>=dp[i+1][j])){rows.push({kind:'add',text:b[j++]});}else if(i<a.length){rows.push({kind:'del',text:a[i++]});}}return rows;}

