  useEffect(()=>{const onMessage=(e:MessageEvent)=>{if(e.source!==terminalFrame.current?.contentWindow)return;const d=e.data as {pothubRun?:string;type?:string;text?:string};if(!d?.pothubRun||d.pothubRun!==runId)return;if(d.type==='done'){setRunOutput(v=>v+'\n'+(d.text||'Finished'));return;}setRunOutput(v=>`${v}\n${d.type==='error'?'ERROR: ':d.type==='warn'?'WARN: ':''}${d.text||''}`);};window.addEventListener('message',onMessage);return()=>window.removeEventListener('message',onMessage);},[runId]);
